#[cfg(feature = "serde")]
fn list_builds_toon_options_from_serializable_struct_slice() {
    #[derive(serde::Serialize)]
    struct Issue {
        number: u64,
        title: String,
        state: String,
    }

    let issues = vec![Issue { number: 51815, title: "[Bug]: Telegram plugin".to_string(), state: "open".to_string() }];
