use michi_toon::{escape_value, list, render_toon, ToonOptions, Value};
use serde::Serialize;

#[derive(Serialize)]
struct OptionalField {
    id: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    url: Option<&'static str>,
}

fn main() {
    let original = r"C:\src\a,b";
    let escaped = escape_value(original);
    println!("escape input={original:?} wire={escaped:?}");

    let opts = ToonOptions::new("files", vec!["path".into()], vec![vec![Value::from(original)]]);
    println!("render_toon={:?}", render_toon(&opts).unwrap());

    let rows = [OptionalField { id: 1, url: None }, OptionalField { id: 2, url: Some("https://x") }];
    println!("list={:?}", list("items", &rows).unwrap());

    let big = u64::MAX;
    let opts = ToonOptions::new("ids", vec!["id".into()], vec![vec![Value::from(big)]]);
    println!("manual_u64={:?}", render_toon(&opts).unwrap());
    println!("serde_u64={:?}", list("ids", &[OptionalField { id: big, url: None }]).unwrap());
    let json = serde_json::to_value(big).unwrap();
    println!("serde_json_number={json} as_i64={:?} as_f64={:?}", json.as_i64(), json.as_f64());
}

