    let fields_str = rest.strip_prefix('{')?.strip_suffix(":")?.strip_suffix('}')?;
    let fields: Vec<String> =
        if fields_str.is_empty() { Vec::new() } else { fields_str.split(',').map(str::to_string).collect() };

