use michi_core::toon::{escape_value, list, render_toon, ToonOptions, Value};
use serde::Serialize;

#[derive(Serialize)]
struct OptionalField {
    id: u64,
    #[serde(skip_serializing_if = "Option::is_none")]
    url: Option<&'static str>,
}

fn main() {
    println!("escaped={:?}", escape_value(r"C:\src\a,b"));
    let path = ToonOptions::new("file", vec!["path".into()], vec![vec![Value::from(r"C:\src\a,b")]]);
    println!("quoted_path={:?}", render_toon(&path).unwrap());
    let rows = [OptionalField { id: 1, url: None }, OptionalField { id: 2, url: Some("https://x") }];
    println!("optional_column={:?}", list("items", &rows).unwrap());
    let big = u64::MAX;
    let numeric = ToonOptions::new("ids", vec!["id".into()], vec![vec![Value::from(big)]]);
    println!("manual_u64={:?}", render_toon(&numeric).unwrap());
    println!("serde_u64={:?}", list("ids", &[OptionalField { id: big, url: None }]).unwrap());
    let short_numeric = ToonOptions::new("ids", vec!["id".into()], vec![vec![Value::from(big)]]).max_cell_len(5);
    println!("manual_u64_max_cell_5={:?}", render_toon(&short_numeric).unwrap());
    let boundary_numeric = ToonOptions::new("ids", vec!["id".into()], vec![vec![Value::from(i64::MAX as u64)]]).max_cell_len(5);
    println!("manual_i64_max_cell_5={:?}", render_toon(&boundary_numeric).unwrap());
}
